fn unit_seconds(rank: Int) -> Int {
  if rank == 0 {
    return 86400
  }
  if rank == 1 {
    return 3600
  }
  if rank == 2 {
    return 60
  }
  return 1
}

pub fn duration(s: Str) -> Result[Int, Str] {
  var total = 0
  var cur = ""
  var prev_rank = -1
  for c in s.chars() {
    if "0123456789".contains(c) {
      cur = cur + c
    } else {
      let rank = "dhms".index_of(c).unwrap_or(-1)
      if rank == -1 or rank <= prev_rank or cur == "" {
        return Err("invalid duration")
      }
      total = total + cur.to_int().unwrap_or(0) * unit_seconds(rank)
      prev_rank = rank
      cur = ""
    }
  }
  if cur != "" or prev_rank == -1 {
    return Err("invalid duration")
  }
  return Ok(total)
}
